    static Map<Long,Boolean> wire(CaptureLog capture)throws Exception {
        var lines=Files.readAllLines(capture.path());for(int n=lines.size()-1;n>=0;n--)if(lines.get(n).contains("S_ATTACK_MANY")) {
            var matcher=java.util.regex.Pattern.compile("\\\"plain\\\":\\\"([0-9A-F ]+)\\\"").matcher(lines.get(n));check(matcher.find(),"captured native multi-target plaintext");var hex=matcher.group(1).split(" ");byte[] bytes=new byte[hex.length];for(int i=0;i<hex.length;i++)bytes[i]=(byte)Integer.parseInt(hex[i],16);var b=ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);check(bytes[17]==0,"caster-centered packet retains native type0");int count=Short.toUnsignedInt(b.getShort(20));check(bytes.length==22+count*5,"native target count/length agrees");b.position(22);var result=new LinkedHashMap<Long,Boolean>();for(int i=0;i<count;i++){long id=Integer.toUnsignedLong(b.getInt());boolean hit=(b.get()&0x20)!=0;check(result.put(id,hit)==null,"no duplicate native wire target="+id);}return result;
        }throw new AssertionError("missing native Counter Detection packet");
    }
